import {createTrashUI} from './trash-ui.js';
// Presentation and lifecycle controls; never alter a project's internal ID.
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function projectSelectHTML(catalog,selected='',includeArchived=false,environmentLabel=()=> ''){
  const groups=new Map();
  for(const item of catalog){if(item.lifecycle?.state==='ARCHIVED'&&!includeArchived&&(item.selectionValue??item.project)!==selected)continue;const key=item.logicalProjectId||'';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(item);}
  const option=item=>`<option value="${escape(item.selectionValue??item.project)}" title="${escape(item.project)}" data-environment-mode="${escape(item.environmentMode)}"${item.machine?` data-project="${escape(item.project)}" data-machine="${escape(item.machine)}" data-owner-id="${escape(item.ownerId||'')}"`:''}>${escape(item.displayName||item.project)}${item.ownerName?' · '+escape(item.ownerName):''}${environmentLabel(item.environmentMode)?' · '+escape(environmentLabel(item.environmentMode)):''}${item.machine?' · '+escape(item.machine):''}${item.pending?' · 待确认':''}${item.lifecycle?.state==='ARCHIVED'?' · 已归档':''}</option>`;
  return '<option value="">默认项目</option>'+[...groups].map(([id,items])=>id?`<optgroup label="${escape(items[0].logicalProjectName||'项目组')}">${items.map(option).join('')}</optgroup>`:items.map(option).join('')).join('');
}
export function createProjectManagement({getContext,call,run,refresh,select}){
  const details=document.createElement('details');details.id='project-management';details.className='execution-panel project-management';
  details.innerHTML=`<summary>整理项目</summary><label class="project-archive-filter"><input type="checkbox" data-include-archived>显示归档项目</label><div class="project-management-current"><p data-project-identity class="mono"></p><form data-label-form><label>显示名称<input data-display-name maxlength="80"></label><button class="button" type="submit">保存名称</button></form><form data-group-form><label>项目组<select data-group-select><option value="">新建项目组</option></select></label><label>组名称<input data-group-name maxlength="80"></label><div class="file-actions"><button class="button" type="submit">保存归组</button><button class="button" type="button" data-group-remove>解除归组</button></div></form><div class="file-actions"><button class="button" type="button" data-project-archive>归档</button><button class="button danger" type="button" data-project-delete>删除项目</button></div><p class="muted">删除后 7 天内可恢复，可能影响正在运行的任务。</p></div><button class="button quiet" type="button" data-project-catalog>查看跨机项目</button><div data-catalog-output></div><p data-management-status role="status"></p>`;
  const q=s=>details.querySelector(s);let identity='',groups=[],catalogRead=null,catalogAt=0;const keys=new Map();
  const message=text=>{q('[data-management-status]').textContent=text;};
  const ref=()=>{const c=getContext();return {machine:c.machine,project:c.project,...(c.ownerId?{ownerId:c.ownerId}:{})};};
  const same=token=>token===getContext().token;
  const action=(button,fn)=>run(button,async()=>{const token=getContext().token;try{await fn(token);}catch(error){if(same(token))message(error.message);throw error;}});
  const trash=createTrashUI({call,getContext,changed:async(row,result)=>{if(result.state==='RESTORED')await refresh({restored:row.project});}});details.append(trash.element);
  function renderGroups(){const info=getContext().info,old=q('[data-group-select]').value;q('[data-group-select]').innerHTML='<option value="">新建项目组</option>'+groups.map(g=>`<option value="${escape(g.id)}">${escape(g.name)}</option>`).join('');if(info?.logicalProjectId&&!groups.some(g=>g.id===info.logicalProjectId))q('[data-group-select]').insertAdjacentHTML('beforeend',`<option value="${escape(info.logicalProjectId)}">${escape(info.logicalProjectName)}</option>`);q('[data-group-select]').value=old||info?.logicalProjectId||'';}
  q('[data-include-archived]').addEventListener('change',()=>refresh({presentationOnly:true}));
  q('[data-label-form]').addEventListener('submit',event=>{event.preventDefault();action(event.submitter,async token=>{await call('projects.label.set',{...ref(),displayName:q('[data-display-name]').value});if(same(token)){message('名称已保存。');await refresh();}});});
  q('[data-group-select]').addEventListener('change',()=>{q('[data-group-name]').value=groups.find(g=>g.id===q('[data-group-select]').value)?.name||'';});
  q('[data-group-form]').addEventListener('submit',event=>{event.preventDefault();action(event.submitter,async token=>{
    const reference=ref(),id=q('[data-group-select]').value||crypto.randomUUID();
    const group=q('[data-group-select]').value?await call('projects.group.get',{id}):{members:[]};if(!same(token))return;
    const members=(group.members||[]).filter(row=>!(row.machine===reference.machine&&row.project===reference.project&&row.ownerId===reference.ownerId));members.push(reference);
    await call('projects.group.set',{id,displayName:q('[data-group-name]').value,members,primary:group.primary||reference});if(same(token)){message('归组已保存。');await refresh();}
  });});
  q('[data-group-remove]').addEventListener('click',event=>action(event.target,async token=>{const id=getContext().info?.logicalProjectId;if(!id)return;const reference=ref(),group=await call('projects.group.get',{id});if(!same(token))return;const members=group.members.filter(row=>!(row.machine===reference.machine&&row.project===reference.project&&row.ownerId===reference.ownerId));await call('projects.group.set',{id,displayName:group.displayName,members,primary:members[0]||null});if(same(token)){message('已解除归组。');await refresh();}}));
  q('[data-project-catalog]').addEventListener('click',async event=>{
    if(catalogRead||Date.now()-catalogAt<30000)return;
    const token=getContext().token,read={};catalogRead=read;event.target.disabled=true;message('正在读取跨机项目…');
    try{const result=await call('projects.catalog',{includeArchived:true});if(!same(token))return;groups=(result.groups||[]).filter(row=>row.logical);const output=q('[data-catalog-output]');output.replaceChildren();for(const group of result.groups||[])for(const item of group.instances||[]){const button=document.createElement('button');button.className='button quiet';button.textContent=`${item.machine} · ${item.ownerName||''} · ${item.displayName||item.project}`;button.addEventListener('click',()=>select(item.machine,item.project,item.ownerId));output.append(button);}renderGroups();catalogAt=Date.now();message(result.partial?'部分服务器未响应，可稍后刷新。':'项目已更新。');}
    catch(error){if(same(token)&&error.name!=='AbortError')message(error.message);}
    finally{if(catalogRead===read){catalogRead=null;const c=getContext();q('[data-project-catalog]').disabled=!c.enabled||c.locked;}}
  });
  q('[data-project-archive]').addEventListener('click',event=>action(event.target,async token=>{const archived=getContext().info?.lifecycle?.state==='ARCHIVED';await call(archived?'projects.unarchive':'projects.archive',ref());if(same(token)){message(archived?'已取消归档。':'已归档。');await refresh();}}));
  q('[data-project-delete]').addEventListener('click',event=>action(event.target,async token=>{const reference=ref(),scope=JSON.stringify([getContext().owner,reference]),key=keys.get(scope)||crypto.randomUUID();keys.set(scope,key);message('删除编号：'+key);const result=await call('projects.retire',{...reference,key});if(!same(token))return;if(result.state==='TRASHED'){keys.delete(scope);message('已删除，7 天内可在回收站恢复。');await refresh({retired:reference});}else message('结果未知，请按原编号查询：'+key);trash.element.open=true;await trash.load();}));
  return {element:details,includeArchived:()=>q('[data-include-archived]').checked,invalidate(){catalogAt=0;},update(){const c=getContext(),next=JSON.stringify([c.owner,c.machine,c.ownerId,c.project]);if(identity!==next){identity=next;groups=[];catalogRead=null;catalogAt=0;q('[data-catalog-output]').replaceChildren();message('');renderGroups();}q('.project-management-current').hidden=!c.project;q('[data-project-identity]').textContent=c.project?c.machine+' / '+c.project:'';if(document.activeElement!==q('[data-display-name]'))q('[data-display-name]').value=c.info?.displayName||c.project||'';q('[data-project-archive]').textContent=c.info?.lifecycle?.state==='ARCHIVED'?'取消归档':'归档';for(const input of details.querySelectorAll('button,input,select'))input.disabled=!c.enabled||c.locked;q('[data-project-catalog]').disabled||=!!catalogRead;trash.update();}};
}
